async function o(e,n){if(e)try{const s=await(await fetch(`${window.APP_CONFIG.baseUrl}api/resend-verification`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:e,resume_url:window.location.href})})).json();n&&(n.innerHTML=s.messages.map(r=>`<p class="${s.success?"text-green-500":"text-red-500"} text-sm mt-2 font-bold">${r}</p>`).join(""))}catch(t){console.error("Resend failed:",t)}}export{o as r};
